<?php require_once __DIR__.'/chart_local.php'; function relplot($width=650,$height=400){$r=db_query("SELECT status,SUM(entries) FROM release_stat_history WHERE date>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 4 WEEK) GROUP BY status ORDER BY SUM(entries) DESC",'ro');$d=[];while($x=mysqli_fetch_row($r))$d[]=[$x[0],(float)$x[1]];echo '<div id="relchart_div">'.atlas_chart_bars($d,'Installation activities',$width,$height).'</div>';}
